  const sourceH1 = cleanInline(lines.shift().replace(/^#\s+/, ""));
  const title = metadata.title || sourceH1;
  if (!title) throw new Error(`Reader-facing title is empty for ${item.slug}.`);

  const externalSources = [];
  const intro = [];
  const sections = [];
  let current = null;
  let paragraphLines = [];
