    titleCounts.set(baseTitle, seen + 1);
    const sectionTitle = seen === 0 ? baseTitle : `${baseTitle} — ادامه${seen > 1 ? ` ${seen + 1}` : ""}`;
    current = { title: sectionTitle, paragraphs: [], bullets: [] };
    sections.push(current);
