  const drafts = await sql`select article.slug from public.wiki_article_drafts draft join public.wiki_articles article on article.id = draft.article_id where article.slug = any(${TARGET_SLUGS}::text[])`;
  const jobs = await sql`select article.slug, job.status from halleus_private.wiki_publish_jobs job join public.wiki_articles article on article.id = job.article_id where article.slug = any(${TARGET_SLUGS}::text[]) and job.status in ('queued','running','retry','failed')`;
