  const row = relations[0] ?? {};
  for (const key of ['articles','revisions','links','drafts','jobs']) if (!row[key]) throw new Error(`SAFETY_FATAL missing required relation: ${key}`);
  const columns = await sql`select column_name from information_schema.columns where table_schema='public' and table_name='wiki_internal_links'`;
  const names = new Set(columns.map((item) => String(item.column_name)));
