  for (const id of inlineIds) await tx`insert into public.wiki_internal_links (source_article_id,target_stable_id,link_kind,source_token,activation_status,activated_at,last_verified_at) values (${row.id}::uuid,${id},'inline',${`[[article:${id}]]`},${ready.has(id)?'active':'pending'},now(),now())`;
  for (const id of relatedIds) await tx`insert into public.wiki_internal_links (source_article_id,target_stable_id,link_kind,source_token,activation_status,activated_at,last_verified_at) values (${row.id}::uuid,${id},'related',${id},${ready.has(id)?'active':'pending'},now(),now()) on conflict do nothing`;
