      const row = lockedBySlug.get(article.slug);
      const snapshot = snapshotFromRow(row, article);
      assertSnapshotShape(snapshot);
      const changed = candidateChanged(row, article, snapshot);
      if (!changed) { applied.push({ slug: article.slug, changed: false, version: Number(row.content_version) }); continue; }
      const revRows = await tx`select coalesce(max(revision_number),0)::int + 1 as next_revision from public.wiki_article_revisions where article_id=${row.id}::uuid`;
      const revisionNumber = Number(revRows[0]?.next_revision ?? 1);
      await tx`insert into public.wiki_article_revisions (article_id,revision_number,snapshot,change_note,created_by,revision_status,published_at) values (${row.id}::uuid,${revisionNumber},${tx.json(snapshot)},${CHANGE_NOTE},null,'published',now())`;
